// Package handlers implements gatewayapi.StrictServerInterface (generated by oapi-codegen from
// contracts/openapi/gateway.yaml) on top of the generated gRPC clients. Success responses use
// the generated per-status types, so a contract change breaks the build here. Failures are
// returned as errors and rendered by the server's problem handler, which only emits statuses
// the operation documents.
package handlers

import (
	"context"
	"errors"
	"time"

	aggregatorv1 "github.com/Azzkaaaa/Tugas-Besar-AAT-M1/packages/bnpb-aggregator-go/bnpb/aggregator/v1"
	feedv1 "github.com/Azzkaaaa/Tugas-Besar-AAT-M1/packages/bnpb-aggregator-go/bnpb/feed/v1"
	notificationv1 "github.com/Azzkaaaa/Tugas-Besar-AAT-M1/packages/bnpb-aggregator-go/bnpb/notification/v1"
	webhookv1 "github.com/Azzkaaaa/Tugas-Besar-AAT-M1/packages/bnpb-aggregator-go/bnpb/webhook/v1"
	gw "github.com/Azzkaaaa/Tugas-Besar-AAT-M1/packages/bnpb-gateway-go/gatewayapi"

	"github.com/Azzkaaaa/Tugas-Besar-AAT-M1/services/api-gateway/internal/problem"
)

var _ gw.StrictServerInterface = (*Handlers)(nil)

// Clients are the backend gRPC clients.
type Clients struct {
	Aggregator   aggregatorv1.AggregatorServiceClient
	Notification notificationv1.DangerNotificationServiceClient
	Webhook      webhookv1.WebhookServiceClient
	Feed         feedv1.EventFeedServiceClient
}

type Handlers struct {
	Clients Clients
	// Timeout bounds unary backend calls; feeds have no deadline.
	Timeout time.Duration
	// Heartbeat is the SSE keepalive comment interval.
	Heartbeat time.Duration
}

func (h *Handlers) unary(ctx context.Context) (context.Context, context.CancelFunc) {
	return context.WithTimeout(ctx, h.Timeout)
}

// upstream converts a mapping or gRPC failure into a problem.
func upstream(err error) error {
	var gatewayErr *problem.Error
	if errors.As(err, &gatewayErr) {
		return gatewayErr
	}
	return problem.FromGRPC(err)
}
